_IDX = {"kk": 0, "en": 1, "tr": 2}

def auto_tr(text):
    lang = get_language()
    if lang == "ru" or not isinstance(text, str):
        return text
    t = AUTO.get(text.strip())
    if t:
        return t[_IDX[lang]]
    for pattern, repl in RULES:
        m = re.match(pattern, text.strip())
        if m:
            return repl[_IDX[lang]].format(m.group(1))
    res = text
    for k, v in _FRAG_SORTED:
        if k in res:
            res = res.replace(k, v[_IDX[lang]])
    return res

def _patch_init(cls):
    orig = cls.__init__
    def __init__(self, master=None, *a, **kw):
        for k in ("text", "label", "placeholder_text", "title"):
            if kw.get(k):
                kw[k] = auto_tr(kw[k])
        if isinstance(kw.get("values"), list):
            kw["values"] = [auto_tr(v) for v in kw["values"]]
        orig(self, master, *a, **kw)
    cls.__init__ = __init__
    orig_conf = cls.configure
    def configure(self, *a, **kw):
        for k in ("text", "label", "placeholder_text"):
            if kw.get(k):
                kw[k] = auto_tr(kw[k])
        if isinstance(kw.get("values"), list):
            kw["values"] = [auto_tr(v) for v in kw["values"]]
        return orig_conf(self, *a, **kw)
    cls.configure = configure
    if hasattr(cls, "set"):
        orig_set = cls.set
        def set(self, value, *a, **kw):
            return orig_set(self, auto_tr(value), *a, **kw)
        cls.set = set

for _c in (ctk.CTkButton, ctk.CTkLabel, ctk.CTkEntry, ctk.CTkCheckBox,
           ctk.CTkRadioButton, ctk.CTkOptionMenu, ctk.CTkComboBox):
    _patch_init(_c)

def _patch_textbox():
    orig = ctk.CTkTextbox.insert
    def insert(self, index, chars, *tags):
        return orig(self, index, auto_tr(chars), *tags)
    ctk.CTkTextbox.insert = insert
_patch_textbox()

def _patch_mb(fn):
    orig = getattr(messagebox, fn)
    def w(title, message, *a, **kw):
        return orig(auto_tr(title), auto_tr(message), *a, **kw)
    setattr(messagebox, fn, w)

for _f in ("showinfo", "showwarning", "showerror", "askyesno", "askokcancel"):
    _patch_mb(_f)